// The test rig's matrix (the workspace's rig/MATRIX.md, generated by its rig/bin/matrix.py) read
// into what the feature tables need: each row (an OS and what readied the machine) and how each of
// its cells last went. A snapshot of it is committed (tests/features-rig.json), so FEATURES.md is
// made the same anywhere, with or without the workspace; `pnpm features --matrix <MATRIX.md>`
// refreshes it.
import type { Platform } from "./registry.ts";

export type Result = "pass" | "fail" | "skip" | "notrun";

/** A row of the matrix: the OS (`debian-13`, `macos-arm64`…), what readied the machine (`golden`,
 *  `golden:libvirt`, a setup path such as `docker+vm`, `host:utm`…), and its cells by column. */
type RigRow = { os: string; setup: string; cells: Record<string, Result> };

export type RigSnapshot = {
  /** When the rig generated the matrix this was read from. */
  generated: string;
  /** The lab-run columns, in the matrix's order. */
  columns: string[];
  rows: RigRow[];
};

/** The matrix's column titles and their ids (the rig's rig/lib/report/matrix/grid.py COLUMNS). */
export const RIG_COLUMNS: readonly (readonly [string, string])[] = [
  ["machine-setup", "Machine setup"],
  ["container", "Containers"],
  ["docker-vm", "Containers in a VM"],
  ["vm", "VMs"],
  ["per-machine", "One VM per machine"],
  ["attack-box:docker", "Box: container"],
  ["attack-box:docker-vm", "Box: in a VM"],
  ["attack-box:vm", "Box: VM"],
  ["server:proxmox", "Proxmox"],
  ["server:esxi", "ESXi"],
  ["cloud", "Cloud"],
  ["desktop-e2e", "App E2E"],
  ["package", "Package"],
  ["repos", "Repos"],
];

const SYMBOL: Record<string, Result> = { "✅": "pass", "❌": "fail", "⏭": "skip", "`·`": "notrun", "·": "notrun" };

const cellsOf = (row: string) =>
  row
    .trim()
    .replace(/^\||\|$/g, "")
    .split("|")
    .map((c) => c.trim());

/** The platform an OS row of the matrix is. */
export const platformOf = (os: string): Platform => (os.startsWith("windows") ? "windows" : os.startsWith("macos") ? "macos" : "linux");

/** The snapshot of the matrix in `markdown` (between its `matrix:begin` and `matrix:end` marks). */
export function parseMatrix(markdown: string): RigSnapshot {
  const block = /<!-- matrix:begin[^>]*-->([\s\S]*?)<!-- matrix:end -->/.exec(markdown)?.[1];
  if (!block) throw new Error("no generated matrix (<!-- matrix:begin … matrix:end -->) in it");
  const lines = block.split("\n").filter((l) => l.trim().startsWith("|"));
  const columns = cellsOf(lines[0] ?? "")
    .slice(2)
    .map((title) => {
      const id = RIG_COLUMNS.find(([, t]) => t === title)?.[0];
      if (!id) throw new Error(`unknown matrix column "${title}": add it to RIG_COLUMNS (scripts/features/matrix.ts)`);
      return id;
    });
  const rows: RigRow[] = [];
  let os = "";
  for (const line of lines.slice(2)) {
    const [first = "", setup = "", ...values] = cellsOf(line);
    os = first.replace(/\*/g, "") || os;
    const cells: Record<string, Result> = {};
    values.forEach((v, i) => {
      if (v in SYMBOL) cells[columns[i]] = SYMBOL[v];
    });
    rows.push({ os, setup, cells });
  }
  return { generated: /\(generated ([^)]+)\)/.exec(block)?.[1] ?? "", columns, rows };
}

/** A feature's rig reference: a column, and after `@` the rows it means, by what readied them:
 *  `vm@qemu` is the VM column of every row readied for QEMU (`golden:qemu`, `host:qemu`, the
 *  `qemu` setup path), `machine-setup@docker+vm` that path's own row. */
function splitRig(ref: string): { column: string; setup: string | null } {
  const at = ref.indexOf("@");
  return at < 0 ? { column: ref, setup: null } : { column: ref.slice(0, at), setup: ref.slice(at + 1) };
}

const rowMatches = (row: RigRow, setup: string | null) => setup === null || row.setup === setup || row.setup.split(":").at(-1) === setup;

/** The results of the cells `refs` name, on `platform` (all platforms when null). */
export function rigResults(rig: RigSnapshot, refs: readonly string[], platform: Platform | null): Result[] {
  return refs.flatMap((ref) => {
    const { column, setup } = splitRig(ref);
    return rig.rows
      .filter((r) => (platform === null || platformOf(r.os) === platform) && rowMatches(r, setup) && column in r.cells)
      .map((r) => r.cells[column]);
  });
}

/** Why a rig reference names no cell, or null when it names some. */
export function rigRefProblem(rig: RigSnapshot, ref: string): string | null {
  const { column, setup } = splitRig(ref);
  if (!rig.columns.includes(column)) return `no rig column ${column} (known: ${rig.columns.join(", ")})`;
  if (setup !== null && !rigResults(rig, [ref], null).length) return `no rig row readied by ${setup} has a ${column} cell`;
  return null;
}

/** How a platform's cells among `refs` last went, best first: one passed, else one failed, else
 *  one was skipped, else they exist but never ran; `none` when the platform has no such cell. */
export function rigState(rig: RigSnapshot, refs: readonly string[], platform: Platform): Result | "none" {
  const results = rigResults(rig, refs, platform);
  return (["pass", "fail", "skip", "notrun"] as const).find((k) => results.includes(k)) ?? "none";
}
